-- ============================================================================
-- MIGRACJA 004: Poprawne rozłożenie istniejących nut na nuty głowy / serca / bazy
-- ----------------------------------------------------------------------------
-- PROBLEM: wcześniejsza migracja (003) przenosiła wszystkie stare nuty do
-- "nuty głowy", bo nie było w nich informacji o podziale piramidy zapachowej.
-- Ten skrypt rozkłada je na 3 grupy (głowa / serce / baza) na podstawie
-- kategorii nuty (tej samej logiki, jakiej używa aplikacja przy dodawaniu
-- perfum z wyszukiwarki - patrz classifyNotePosition w lib/fragrance-api.ts).
--
-- KATEGORIE -> GRUPA:
--   głowa (top):   Cytrusowe, Owocowe, Zielone, Świeże, Aromatyczne
--   serce (heart): Kwiatowe, Korzenne, Orientalne, Napoje
--   baza (base):   Słodkie, Drzewne, Piżmowe, Ambrowe, Skórzane, Wodne i reszta
--   nieznane nuty: domyślnie serce (heart) - bezpieczny środek
--
-- BEZPIECZEŃSTWO:
--   * całość w transakcji (błąd = ROLLBACK, nic się nie psuje),
--   * skrypt jest IDEMPOTENTNY (można uruchamiać wielokrotnie),
--   * najpierw tworzy kopię zapasową kolumny "notes" (perfumes_notes_backup),
--   * przetwarza TYLKO wiersze, w których serce i baza są nadal puste
--     (czyli wszystkie nuty siedzą w głowie) - ręcznie uzupełnionych
--     piramid NIE nadpisuje,
--   * niczego nie usuwa.
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1) Kopia zapasowa starych nut (jednorazowa, nie nadpisuje)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS perfumes_notes_backup (
  perfume_id   UUID PRIMARY KEY,
  notes_flat   TEXT[],
  backed_up_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO perfumes_notes_backup (perfume_id, notes_flat)
SELECT id, notes
FROM perfumes
WHERE notes IS NOT NULL
  AND cardinality(notes) > 0
ON CONFLICT (perfume_id) DO NOTHING;

-- ----------------------------------------------------------------------------
-- 2) Kolumny strukturalne (jeśli jeszcze nie istnieją - no-op)
-- ----------------------------------------------------------------------------
ALTER TABLE perfumes
  ADD COLUMN IF NOT EXISTS notes_top   JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS notes_heart JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS notes_base  JSONB NOT NULL DEFAULT '[]'::jsonb;

-- ----------------------------------------------------------------------------
-- 3) Funkcja klasyfikująca nutę do grupy (głowa/serce/baza).
--    Mapowanie wygenerowane ze słownika nut (lib/notes-dictionary.ts).
--    Nazwa jest normalizowana tak samo jak w aplikacji (translateNote).
-- ----------------------------------------------------------------------------
