erpentine":"base","green-banana":"top","blue-pea-flower":"heart","ube":"base","madonna-lily":"heart","kabosu":"top","cedramber":"base","ethyl-vanilin":"base","barnyard":"base","ambrexolide":"base","sublimolide":"base","lollipop":"base","culantro":"top","orange-jasmine":"heart","sugar-candy":"base","achillea-olympus":"top","olymra-plant-accord":"top","naphthalene":"base","party-balloons":"base","kanzan-cherry":"heart","taiwan-incense-cedar":"base","phoenix-dan-cong-oolong":"top","crispy-roll":"base","murcott":"top","muscovado":"base","black-lemon":"top","ghaf-tree":"base","cola":"heart","hojicha":"top","bouvardia":"heart","apricot-wood":"base","osmanthus-milk":"heart","guava-nectar":"top","strawberry-gum":"top","doremox":"base","champagne-cola":"heart","verjuice":"heart","blue-crystal":"base","white-powder":"base","pine-nuts":"top","garlic-blossom":"heart","vieux-carr":"heart","samphire":"top","green-petals":"heart","banana-peel":"top","boba":"base","linalool":"base","powdered-leaf":"top","fruity-powder":"top","radish":"top","corydalis":"heart","grogue":"heart","cream-cheese-frosting":"base","tarte-tatin":"base","coriander-flower":"heart","kiwano":"top"}'::jsonb;
BEGIN
  k := lower(regexp_replace(
    regexp_replace(
      translate(lower(p_name), 'ąćęłńóśźż', 'acelnoszz'),
      '\s+', '-', 'g'
    ),
    '[^a-z0-9-]', '', 'g'
  ));
  g := groups->>k;
  IF g IS NOT NULL THEN RETURN g; END IF;
  RETURN 'heart';
END;
$$;

-- ----------------------------------------------------------------------------
-- 4) Rozłożenie nut: TYLKO wiersze, w których serce i baza są puste
--    (cała piramida siedzi w "głowie"). Ręcznie wypełnione piramidy są pomijane.
-- ----------------------------------------------------------------------------
UPDATE perfumes p
SET
  notes_top   = COALESCE(sub."top",   '[]'::jsonb),
  notes_heart = COALESCE(sub."heart", '[]'::jsonb),
  notes_base  = COALESCE(sub."base",  '[]'::jsonb)
FROM (
  SELECT
    p2.id,
    jsonb_agg(jb) FILTER (WHERE classify_note(jb->>'name') = 'top')   AS "top",
    jsonb_agg(jb) FILTER (WHERE classify_note(jb->>'name') = 'heart') AS "heart",
    jsonb_agg(jb) FILTER (WHERE classify_note(jb->>'name') = 'base')  AS "base"
  FROM perfumes p2
  CROSS JOIN LATERAL jsonb_array_elements(p2.notes_top) jb
  WHERE p2.notes_heart = '[]'::jsonb
    AND p2.notes_base  = '[]'::jsonb
  GROUP BY p2.id
) sub
WHERE p.id = sub.id;

-- ----------------------------------------------------------------------------
-- 5) Indeksy GIN (idempotentne)
-- ----------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_perfumes_notes_top   ON perfumes USING GIN (notes_top);
CREATE INDEX IF NOT EXISTS idx_perfumes_notes_heart ON perfumes USING GIN (notes_heart);
CREATE INDEX IF NOT EXISTS idx_perfumes_notes_base  ON perfumes USING GIN (notes_base);

COMMIT;

-- ----------------------------------------------------------------------------
-- 6) WERYFIKACJA (tylko odczyt):
--    * rows_with_structured_notes - ile wierszy ma teraz rozłożone nuty
--    * rows_still_all_in_top      - powinno być 0 (nic nie zostało w głowie)
--    * rows_with_flat_notes       - ile wierszy miało stare nuty
--    * backup_count               - ile wierszy w kopii zapasowej
-- ----------------------------------------------------------------------------
SELECT
  COUNT(*) FILTER (
    WHERE notes_heart <> '[]'::jsonb OR notes_base <> '[]'::jsonb
  ) AS rows_with_structured_notes,
  COUNT(*) FILTER (
    WHERE jsonb_array_length(notes_top) > 0
      AND notes_heart = '[]'::jsonb
      AND notes_base  = '[]'::jsonb
  ) AS rows_still_all_in_top,
  COUNT(*) FILTER (
    WHERE notes IS NOT NULL AND cardinality(notes) > 0
  ) AS rows_with_flat_notes,
  (SELECT COUNT(*) FROM perfumes_notes_backup) AS backup_count
FROM perfumes;

